import React from 'react';
import { useParams } from 'react-router-dom';
import { useQuery } from 'react-query';
import { getUserProfile } from '../api/prompts';
import PromptCard from '../components/prompts/PromptCard';
import { FiUser, FiFileText, FiEye, FiHeart } from 'react-icons/fi';

const UserProfile = () => {
  const { username } = useParams();

  const { data, isLoading, error } = useQuery(
    ['userProfile', username],
    () => getUserProfile(username)
  );

  if (isLoading) {
    return (
      <div className="max-w-4xl mx-auto">
        <div className="animate-pulse">
          <div className="h-32 bg-gray-200 rounded mb-4"></div>
          <div className="h-8 bg-gray-200 rounded mb-4"></div>
          <div className="h-4 bg-gray-200 rounded mb-2"></div>
          <div className="h-4 bg-gray-200 rounded w-3/4"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-4xl mx-auto text-center py-12">
        <div className="text-red-600 text-lg mb-4">Error loading user profile</div>
        <div className="text-gray-600">User not found or profile is private</div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="max-w-4xl mx-auto text-center py-12">
        <div className="text-gray-600 text-lg mb-4">User not found</div>
      </div>
    );
  }

  const { user, prompts, stats } = data;

  return (
    <div className="max-w-4xl mx-auto">
      {/* User Header */}
      <div className="card mb-8">
        <div className="flex items-start space-x-6">
          <div className="w-20 h-20 bg-blue-600 rounded-full flex items-center justify-center">
            <span className="text-white font-bold text-2xl">
              {user.username.charAt(0).toUpperCase()}
            </span>
          </div>
          <div className="flex-1">
            <h1 className="text-3xl font-bold text-gray-900 mb-2">{user.username}</h1>
            {user.bio && (
              <p className="text-grayUncaught runtime errors:
×
ERROR
Request failed with status code 400
AxiosError: Request failed with status code 400
    at settle (http://localhost:3000/static/js/bundle.js:7350:12)
    at XMLHttpRequest.onloadend (http://localhost:3000/static/js/bundle.js:5977:66)
    at Axios.request (http://localhost:3000/static/js/bundle.js:6476:41)
    at async Object.register [as mutationFn] (http://localhost:3000/main.48c7f827b8d14fe7f752.hot-update.js:54:20)-600 mb-4">{user.bio}</p>
            )}
            <div className="flex items-center space-x-6 text-sm text-gray-500">
              <div className="flex items-center space-x-1">
                <FiFileText className="w-4 h-4" />
                <span>{stats.totalPrompts} prompts</span>
              </div>
              <div className="flex items-center space-x-1">
                <FiEye className="w-4 h-4" />
                <span>{stats.totalViews} views</span>
              </div>
              <div className="flex items-center space-x-1">
                <FiHeart className="w-4 h-4" />
                <span>{stats.totalLikes} likes</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* User's Prompts */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900 mb-6">Prompts by {user.username}</h2>
        
        {prompts.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {prompts.map((prompt) => (
              <PromptCard key={prompt._id} prompt={prompt} />
            ))}
          </div>
        ) : (
          <div className="text-center py-12">
            <div className="text-gray-500 text-lg mb-4">No prompts yet</div>
            <p className="text-gray-600">This user hasn't shared any prompts yet.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default UserProfile;
